import { extend } from 'flarum/common/extend';
import UserPage from 'flarum/forum/components/UserPage';
import UserPopularLinksWidget from './components/UserPopularLinksWidget';
export default function addUserPopularLinksWidget() {
  extend(UserPage.prototype, 'sidebarItems', function (items) {
    if (!this.user) return;
    items.add('linkClicksPopular', m(UserPopularLinksWidget, {
      userId: String(this.user.id())
    }), -10);
  });
}